package com.pranit.helpdesk.controller;
import com.pranit.helpdesk.dto.*; import com.pranit.helpdesk.entity.*; import com.pranit.helpdesk.service.TicketService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/tickets") public class TicketController{private final TicketService s;public TicketController(TicketService s){this.s=s;}@PostMapping public ResponseEntity<Ticket> create(@Valid @RequestBody CreateTicketRequest r,Authentication a){return ResponseEntity.status(201).body(s.create(r,a.getName()));}@GetMapping("/mine")public List<Ticket> mine(Authentication a){return s.mine(a.getName());}@GetMapping("/assigned")@PreAuthorize("hasAnyRole('AGENT','ADMIN')")public List<Ticket> assigned(Authentication a){return s.assigned(a.getName());}@GetMapping("/{id}")public Ticket get(@PathVariable Long id){return s.get(id);}@PatchMapping("/{id}")public Ticket update(@PathVariable Long id,@RequestBody UpdateTicketRequest r){return s.update(id,r);}@PostMapping("/{id}/assign/{agent}")@PreAuthorize("hasRole('ADMIN')")public Ticket assign(@PathVariable Long id,@PathVariable String agent){return s.assign(id,agent);}@PostMapping("/{id}/comments")public Comment comment(@PathVariable Long id,@Valid @RequestBody CommentRequest r,Authentication a){return s.comment(id,a.getName(),r.message());}@GetMapping("/{id}/comments")public List<Comment> comments(@PathVariable Long id){return s.comments(id);}}
